using System;using System.IO;using System.Security.Cryptography;using NativeInterval;
class LncInspect {
 static void Main(string[] args){foreach(string path in args){Clip clip;using(var input=File.OpenRead(path))clip=path.EndsWith(".lnc1")?Clip.ReadRaw(input):Clip.ReadDeflate(input);int keys=0,weighted=0,nonfinite=0,supported=0,unsupported=0,overshoots=0;foreach(var curve in clip.Curves){keys+=curve.Keys.Length;foreach(var key in curve.Keys){if(key.Weighted!=0)weighted++;if(double.IsInfinity(key.In)||double.IsInfinity(key.Out)||double.IsNaN(key.In)||double.IsNaN(key.Out))nonfinite++;}if(curve.Keys.Length<2)continue;for(int i=0;i<curve.Keys.Length-1;i++){var a=curve.Keys[i];var b=curve.Keys[i+1];I bound;if(curve.Bound(a.Time,b.Time,out bound)){supported++;if(bound.Lo<System.Math.Min(a.Value,b.Value)||bound.Hi>System.Math.Max(a.Value,b.Value))overshoots++;}else unsupported++;}}
 byte[] hash;using(var sha=SHA256.Create())hash=sha.ComputeHash(File.ReadAllBytes(path));Console.WriteLine("source="+path+" sha256="+BitConverter.ToString(hash).Replace("-","")+" joints="+clip.JointChannels.Length+" curves="+clip.Curves.Length+" keys="+keys+" weightedKeys="+weighted+" nonfiniteTangents="+nonfinite+" supportedKeyIntervals="+supported+" unsupported="+unsupported+" boundsBeyondEndpoints="+overshoots+" unityEquivalent=false");}}
}
